const API='/api';
const THEMES={teal:{label:'Deep teal',swatch:'#103837'},grey:{label:'Every shade of grey',swatch:'#292d32'},navy:{label:'Navy blue',swatch:'#1a314b'},green:{label:'Dark green',swatch:'#1a3927'},black:{label:'Black',swatch:'#111111'},brown:{label:'Brown',swatch:'#3b281e'}};
const state={token:localStorage.getItem('aura_token')||localStorage.getItem('ic_token')||'',user:null,profile:null,studies:[],progress:[],notes:[],challengeProgress:[],challenges:[],games:[],screen:'today',selected:'',filter:'All',quizResult:null,emailResetReady:false,resetEmail:'',mini:null,theme:'teal'};
const $=selector=>document.querySelector(selector),screen=$('#screen'),overlay=$('#overlay');
function esc(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[char]))}
function themeKey(){return state.profile?.id?`msb_theme:${state.profile.id}`:null}
function applyTheme(name,save=true){state.theme=THEMES[name]?name:'teal';document.documentElement.dataset.theme=state.theme;if(save&&themeKey())localStorage.setItem(themeKey(),state.theme)}
applyTheme('teal',false);
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500)}
async function apiRemote(path,method='GET',body){const form=body instanceof FormData,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),form?60000:25000);try{const res=await fetch(API+path,{method,credentials:'same-origin',signal:controller.signal,headers:{...(body!==undefined&&!form?{'Content-Type':'application/json'}:{}),...(state.token?{Authorization:'Bearer '+state.token}:{})},...(body===undefined?{}:{body:form?body:JSON.stringify(body)})});const data=await res.json().catch(()=>({}));if(controller.signal.aborted)throw Error('Timed out');if(!res.ok){const failure=Error(data.error||`Request failed (${res.status})`);failure.status=res.status;throw failure}return data}catch(error){if(controller.signal.aborted)throw Error(path==='/auth/register'?'The request timed out. Your account may exist. Try signing in before trying signup again.':'The request timed out. Check your connection and try again.');if(error instanceof TypeError){const failure=Error('Could not reach Mind Soul and Body. Check your connection and try again.');failure.offline=true;throw failure}throw error}finally{clearTimeout(timer)}}
function study(id){return state.studies.find(item=>item.id===id)}
function progress(id){return state.progress.find(item=>item.study_id===id)}
function note(id){return state.notes.find(item=>item.study_id===id)?.body||''}
function completed(){return state.progress.filter(item=>item.completed_at).length}
function avatar(){return state.profile?.avatar_data?`<img src="${state.profile.avatar_data}" alt="">`:state.profile?.avatar_key?`<img src="/api/avatars/${encodeURIComponent(state.profile.id)}?v=${Date.now()}" alt="">`:esc((state.profile?.name||'L')[0])}
async function loadAccount(){const [profile,dashboard]=await Promise.all([api('/me'),api('/study/dashboard')]);state.profile=profile;const legacyTheme=localStorage.getItem('msb_theme');applyTheme(localStorage.getItem(themeKey())||legacyTheme||'teal');if(legacyTheme)localStorage.removeItem('msb_theme');state.progress=dashboard.progress||[];state.notes=dashboard.notes||[];state.challengeProgress=dashboard.challenges||[];BibleReader.resetAccount();$('#account-button').innerHTML=avatar()}
function tabFor(name){return ['bible'].includes(name)?'bible':['library','study','notes'].includes(name)?'library':['practice'].includes(name)?'practice':['profile'].includes(name)?'profile': 'today'}
function nav(name,id){if(state.screen==='bible')BibleReader.hide();if(state.screen==='trivia')TriviaGame.hide();state.screen=name;if(id)state.selected=id;state.quizResult=null;if(name==='mini')state.mini=null;document.querySelectorAll('[data-nav]').forEach(button=>button.classList.toggle('active',button.dataset.nav===tabFor(name)));render();window.scrollTo({top:0,behavior:'auto'})}
function lessonCard(item){const done=!!progress(item.id)?.completed_at;return `<button class="card lesson-card" data-lesson="${esc(item.id)}"><span class="lesson-meta">STUDY ${String(item.order).padStart(2,'0')} · ${esc(item.reference)}</span><h3>${esc(item.title)}</h3><p>${esc(item.context)}</p><footer><span class="tag">${done?'✓ Completed':esc(item.theme)}</span><span>Open study ↗</span></footer></button>`}
function challengeScore(id){return state.challengeProgress.find(item=>item.activity_id===id)}
function challengeCard(item,game=false){const saved=challengeScore(item.id);return `<button class="card challenge-card" data-activity="${esc(item.id)}"><span class="lesson-meta">${esc(item.category.toUpperCase())} · ${game?'GAME':esc(item.level.toUpperCase())}</span><span class="challenge-glyph" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7z"/></svg></span><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><footer><span class="tag">${saved?`Best ${saved.best_score}/${game?item.prompts.length:item.questions.length}`:game?'Match the ideas':item.micro?'Start lesson':'Take quiz'}</span><span>Begin ↗</span></footer></button>`}
function section(title,action=''){return `<div class="section-head"><h2>${esc(title)}</h2>${action}</div>`}
function welcome(){screen.innerHTML=`<span class="eyebrow">SCRIPTURE · PRAYER · TRADITION</span><h1>Read deeply. Live faithfully.</h1><p class="lead">Read Scripture with the Orthodox Church. Your notes and progress can stay with your profile.</p>${weeklyDashboard()}<div class="card welcome-action"><h2>Keep your place</h2><p>Create a profile to save notes, reading progress, and highlights across devices.</p><button class="primary" data-action="signup">Create your study profile</button> <button class="secondary" data-action="signin">Sign in</button></div><div class="home-actions"><button class="hub-card" data-nav="bible"><span class="eyebrow">READ</span><strong>The full Bible</strong><span>81 books, notes, and highlights</span></button><button class="hub-card" data-nav="challenges"><span class="eyebrow">PLAY</span><strong>Quizzes & games</strong><span>Survey Says, Jeopardy, and lessons</span></button></div>${section('Start with Scripture')}<div class="lesson-grid">${state.studies.slice(0,4).map(lessonCard).join('')}</div><p class="footnote">Selected passages are from the public-domain King James Version. The study notes are original summaries, not quotations from the Church Fathers or a substitute for guidance from your parish.</p>`}
function studyWeek(){const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-start.getDay());const days=Array(7).fill(0),types=[0,0,0,0];for(const item of state.progress){if(!item.completed_at)continue;const when=new Date(item.completed_at*1000);if(when<start||when>now)continue;days[when.getDay()]++;const ref=study(item.study_id)?.reference||'';types[/^(John|Matthew|Luke|Mark)/.test(ref)?0:/^Psalm/.test(ref)?1:/^(James|1 Corinthians|2 Corinthians|Romans)/.test(ref)?2:3]++}const all=state.progress.filter(item=>item.completed_at).map(item=>new Date(item.completed_at*1000).toDateString());let streak=0,day=new Date(now);day.setHours(0,0,0,0);if(!all.includes(day.toDateString()))day.setDate(day.getDate()-1);while(all.includes(day.toDateString())){streak++;day.setDate(day.getDate()-1)}return {days,types,streak,total:days.reduce((a,b)=>a+b,0)}}
function dailyCard(){const date=new Date();return date.getDay()%2?{book:43,chapter:1,verse:5,name:'John 1:5',text:'And the light shineth in darknesse, and the darknesse comprehended it not.'}:{book:19,chapter:119,verse:105,name:'Psalm 119:105',text:'Thy word is a lampe vnto my feete: and a light vnto my path.'}}

function weeklyDashboard(){const week=studyWeek(),verse=dailyCard(),total=state.studies.length,percent=total?Math.round(completed()/total*100):0;const labels=['Gospels','Psalms','Letters','Other plans'],colors=['#68e6c9','#f4adca','#ffd38d','#bca5ff'];let angle=0;const parts=week.types.map((value,i)=>{const begin=angle;angle+=week.total?value/week.total*360:0;return value?`${colors[i]} ${begin}deg ${angle}deg`:''}).filter(Boolean);const ring=parts.length?`conic-gradient(${parts.join(',')})`:'conic-gradient(#3d374c 0deg 360deg)';return `<section class="daily-stack"><span class="eyebrow">TODAY IN SCRIPTURE</span><h2>${esc(verse.text||'Opening today’s verse…')}</h2><span>${esc(verse.name)} · KJV 1611</span><button class="verse-play" data-daily-read aria-label="Open today’s verse in the Bible"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m9 6 9 6-9 6z"/></svg></button></section><div class="neon-stats"><section class="neon-stat violet"><span class="eyebrow">READING STREAK</span><strong>${week.streak}</strong><span>${week.streak===1?'day':'days'} with completed studies</span></section><section class="neon-stat mint"><span class="eyebrow">THIS WEEK</span><strong>${week.total}</strong><span>${week.total===1?'study chapter':'study chapters'} completed</span></section></div><div class="insights-grid"><section class="card week-panel"><div class="panel-top"><h2>This week</h2><span>${week.total} ${week.total===1?'completion':'completions'}</span></div><div class="week-bars" role="img" aria-label="Study chapters completed Sunday through Saturday: ${week.days.join(', ')}"><div class="bar-lines" aria-hidden="true"></div>${week.days.map((count,i)=>`<div class="bar-day"><i style="height:${count?Math.round(count/Math.max(1,...week.days)*100):0}%"></i><small>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][i]}</small></div>`).join('')}</div></section><section class="card split-panel"><h2>Reading split</h2><p class="small">Completed study chapters this week</p><div class="donut" style="--donut:${ring}" role="img" aria-label="This week’s reading split"><div><strong>${week.total}</strong><span>chapters</span></div></div><div class="split-legend">${labels.map((label,i)=>`<span><i style="background:${colors[i]}"></i>${label}<b>${week.total?Math.round(week.types[i]/week.total*100):0}%</b></span>`).join('')}</div></section></div><section class="progress-orb card"><h2>It's all about progress,<br>not perfection.</h2><div class="orb" aria-hidden="true"></div><strong>${percent}%</strong><span>of your reading path complete</span></section>`}
function today(){if(!state.user)return welcome();const next=state.studies.find(item=>!progress(item.id)?.completed_at)||state.studies[0];screen.innerHTML=`<span class="eyebrow">YOUR READING PATH</span><h1>Peace to you, ${esc(state.profile?.name?.split(' ')[0]||'friend')}.</h1>${!state.user.registered?'<div class="card"><p>Your guest space is temporary. Create an account to keep your notes across devices.</p><button class="primary" data-action="signup">Create account</button></div>':''}${weeklyDashboard()}<section class="card next-study"><div><span class="eyebrow">${completed()===state.studies.length?'RETURN TO THE WORD':'UP NEXT'}</span><h2>${esc(next.title)}</h2><p>${esc(next.reference)} · ${esc(next.theme)}</p></div><button class="primary" data-lesson="${esc(next.id)}">${completed()===state.studies.length?'Read again':'Continue reading'}</button></section><div class="home-actions"><button class="hub-card" data-nav="bible"><span class="eyebrow">READ</span><strong>The full Bible</strong><span>81 books, notes, and highlights</span></button><button class="hub-card" data-nav="challenges"><span class="eyebrow">PLAY</span><strong>Quizzes & games</strong><span>Survey Says, Jeopardy, and lessons</span></button></div>${section('Reading plans','<button class="text-button" data-nav="library">See all plans</button>')}<div class="lesson-grid">${state.studies.slice(0,4).map(lessonCard).join('')}</div><p class="footnote">Study commentary follows the Orthodox tradition as a learning aid. Bring difficult questions to your priest or study group.</p>`}
function library(){const themes=['All',...new Set(state.studies.map(item=>item.theme))];const shown=state.filter==='All'?state.studies:state.studies.filter(item=>item.theme===state.filter);screen.innerHTML=`<span class="eyebrow">THE SCRIPTURE LIBRARY</span><h1>A path through the Word.</h1><p class="lead">Short readings with context, an Orthodox lens, questions, and a practice for the day.</p><div class="filters">${themes.map(theme=>`<button class="filter ${state.filter===theme?'active':''}" data-filter="${esc(theme)}">${esc(theme)}</button>`).join('')}</div><div class="reflect-links"><button class="hub-card" data-nav="notes"><span class="eyebrow">JOURNAL</span><strong>My notes</strong><span>Return to your reflections</span></button><button class="hub-card" data-nav="challenges"><span class="eyebrow">LEARN</span><strong>Games & quizzes</strong><span>Play and practice the lessons</span></button></div><div class="lesson-grid">${shown.map(lessonCard).join('')}</div><p class="footnote">The passages shown here are selected readings, not a complete Bible. Psalm numbering follows both the Septuagint and common English editions where they differ.</p>`}
function reader(){const item=study(state.selected);if(!item){nav('library');return}const saved=note(item.id),done=!!progress(item.id)?.completed_at;screen.innerHTML=`<div class="lesson-top"><button class="text-button back" data-nav="library">← All studies</button><span class="eyebrow">STUDY ${String(item.order).padStart(2,'0')} · ${esc(item.theme.toUpperCase())}</span><h1>${esc(item.title)}</h1><span class="tag">${esc(item.reference)}</span></div><div class="reader-layout"><div class="reader-main"><section class="card reading-card"><button class="text-button" data-bible-open="${esc(item.id)}">Read the full chapter in the Bible ↗</button><span class="eyebrow">READ · KING JAMES VERSION</span><p class="passage">${esc(item.passage)}</p><small class="muted">A selected passage from ${esc(item.reference)}.</small></section><section class="card study-copy"><span class="eyebrow">THE SETTING</span><h2>What is happening?</h2><p>${esc(item.context)}</p></section><section class="card study-copy"><span class="eyebrow">AN ORTHODOX LENS</span><h2>Read with the Church</h2><p>${esc(item.orthodox)}</p></section><section class="card"><span class="eyebrow">REFLECT</span><h2>Take it to heart</h2><ol class="reflection-list">${item.questions.map(question=>`<li>${esc(question)}</li>`).join('')}</ol></section><section class="card"><span class="eyebrow">PRIVATE JOURNAL</span><h2>Your notes</h2><p class="muted">Only your account can read these notes.</p><textarea class="note-field" id="study-note" maxlength="4000" placeholder="What stood out? What will you ask God about?">${esc(saved)}</textarea><div class="note-actions"><button class="primary" data-action="save-note">Save note</button><span class="small" id="note-status">${saved?'Saved to your profile':'Write a thought to remember'}</span></div></section><section class="card"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h2>Two short questions</h2><form id="quiz-form">${item.quiz.map((question,index)=>`<div class="quiz-item"><strong>${index+1}. ${esc(question.prompt)}</strong>${question.choices.map((choice,option)=>`<label class="choice"><input type="radio" name="question-${index}" value="${option}" required> ${esc(choice)}</label>`).join('')}</div>`).join('')}<button class="secondary" type="submit">Check answers</button></form><div id="quiz-result"></div></section></div><aside class="reader-aside"><section class="card"><span class="eyebrow">CARRY IT WITH YOU</span><h2>A practice for today</h2><p class="study-copy">${esc(item.practice)}</p></section><section class="card"><span class="eyebrow">YOUR PLACE</span><h2>${done?'Study completed':'Ready when you are'}</h2><p class="muted">Completion is for your own reading path. You can return any time.</p><button class="${done?'secondary':'primary'}" data-action="toggle-complete">${done?'Mark unfinished':'Mark study complete'}</button></section></aside></div>`}
function practice(){screen.innerHTML=`<span class="eyebrow">A DAILY RHYTHM</span><h1>Take the Word into prayer.</h1><p class="lead">A simple way to read faithfully, without rushing to finish.</p><div class="practice-grid"><section class="card"><span class="number-label">01 · BE STILL</span><h2>Begin with prayer</h2><p>Ask the Holy Spirit to open your heart. Read the passage aloud or slowly enough to hear it.</p></section><section class="card"><span class="number-label">02 · ATTEND</span><h2>Read in context</h2><p>Notice who is speaking, to whom, and what comes before and after. Bring the passage into conversation with the Church's worship.</p></section><section class="card"><span class="number-label">03 · RESPOND</span><h2>Live one thing</h2><p>Write a question, pray with the text, and choose one concrete act of repentance, gratitude, or mercy.</p></section></div>${section('From the studies')}<div class="lesson-grid">${state.studies.map(item=>`<button class="card lesson-card" data-lesson="${esc(item.id)}"><span class="lesson-meta">${esc(item.reference)}</span><h3>${esc(item.title)}</h3><p>${esc(item.practice)}</p><footer><span>Open passage ↗</span></footer></button>`).join('')}</div>`}
function notes(){if(!state.user){welcome();return}const entries=state.notes.filter(item=>item.body.trim()).sort((a,b)=>b.updated_at-a.updated_at);screen.innerHTML=`<span class="eyebrow">ONLY YOU CAN SEE THESE</span><h1>Your study journal.</h1><p class="lead">The questions you keep are part of the journey.</p>${entries.length?`<div class="note-list">${entries.map(entry=>{const item=study(entry.study_id);return `<button class="card note-preview" data-lesson="${esc(entry.study_id)}"><span class="lesson-meta">${esc(item?.reference||'Study')} · ${new Date(entry.updated_at*1000).toLocaleDateString()}</span><h3>${esc(item?.title||'Your study')}</h3><p>${esc(entry.body.slice(0,280))}${entry.body.length>280?'…':''}</p></button>`}).join('')}</div>`:'<div class="empty">No notes yet. Open a study and write down what you notice.</div>'}`}
function profile(){if(!state.user){welcome();return}const p=state.profile||{};screen.innerHTML=`<div class="profile-cover">${p.cover_data?`<img src="${p.cover_data}" alt="Profile cover">`:p.cover_key?`<img src="/api/cover/${encodeURIComponent(p.id)}?v=${Date.now()}" alt="Profile cover">`:''}</div><div class="profile-head"><div class="profile-avatar">${avatar()}</div><div><h1>${esc(p.name||'Your profile')}</h1><p>@${esc(p.handle||'reader')}${p.city?' · '+esc(p.city):''}</p></div></div><p class="lead">${esc(p.bio||'A place to read, reflect, and pray.')}</p><div class="profile-stats"><div><strong>${completed()}</strong><small>studies completed</small></div><div><strong>${state.notes.filter(n=>n.body.trim()).length}</strong><small>private notes</small></div><div><strong>${state.challengeProgress.length}</strong><small>challenges played</small></div></div><section class="card theme-card"><span class="eyebrow">APP APPEARANCE</span><h2>Choose your background</h2><p class="muted">Your palette is saved for this profile on this device.</p><div class="theme-swatches">${Object.entries(THEMES).map(([key,item])=>`<button class="theme-swatch ${state.theme===key?'selected':''}" data-theme-choice="${key}" title="${esc(item.label)}" aria-label="${esc(item.label)}" aria-pressed="${state.theme===key}"><i style="background:${item.swatch}"></i><span>${esc(item.label)}</span></button>`).join('')}</div></section><div class="profile-actions"><button class="secondary" data-nav="bible">Read the Bible</button><button class="secondary" data-nav="notes">My notes</button><button class="primary" data-action="edit-profile">Edit profile</button>${p.registered?'<button class="secondary" data-action="change-password">Change password</button><button class="secondary" data-action="recovery-code">New recovery code</button>':'<button class="secondary" data-action="signup">Finish creating account</button>'}<button class="secondary" data-action="logout">Sign out</button></div><p class="footnote">Your study notes and quiz results are private to this account. Your Bible highlights and reading place are saved to this account.</p>`}
function challengesScreen(){const quizzes=state.challenges.filter(item=>!item.micro),minis=state.challenges.filter(item=>item.micro&&!item.track),scripture=state.challenges.filter(item=>item.track==='Scripture'),councils=state.challenges.filter(item=>item.track==='Seven Councils');screen.innerHTML=`<span class="eyebrow">ORTHODOX THEOLOGY · APOLOGETICS</span><h1>Learn it. Test it. Explain it.</h1><p class="lead">${state.challenges.reduce((sum,item)=>sum+item.questions.length,0)} questions across ${state.challenges.length} tracks, plus two matching games and immediate-feedback mini lessons. Every answer has a reason and a source for further study. Replay to improve your best score.</p><div class="game-stack"><button class="game-layer" data-nav="trivia"><span class="eyebrow">SCRIPTURE GAME</span><strong>Survey Says</strong><span>Open the answer board</span></button><button class="game-layer" data-nav="trivia"><span class="eyebrow">CATEGORY GAME</span><strong>Jeopardy</strong><span>Open the clue board</span></button><button class="game-layer" data-activity="${esc(minis[0]?.id||'')}"><span class="eyebrow">SHORT LESSONS</span><strong>Learn one idea</strong><span>Start an apologetics lesson</span></button></div>${section('Scripture lesson track')}<p class="lead">Book overviews, key stories, and memory verses. Each step saves your best result to your profile.</p><div class="challenge-grid">${scripture.map(item=>challengeCard(item)).join('')}</div>${section('The Seven Ecumenical Councils')}<p class="lead">One short lesson for each council, from Nicaea I to Nicaea II.</p><div class="challenge-grid">${councils.map(item=>challengeCard(item)).join('')}</div>${section('Apologetics mini lessons')}<p class="lead">Learn from each answer, then try again.</p><div class="challenge-grid">${minis.map(item=>challengeCard(item)).join('')}</div>${section('Theology & apologetics quizzes')}<div class="challenge-grid">${quizzes.map(item=>challengeCard(item)).join('')}</div>${section('Timed Scripture games')}<div class="challenge-grid"><button class="card challenge-card" data-nav="trivia"><span class="eyebrow">SOLO OR WITH A FRIEND</span><h3>Answer board & category clues</h3><p>Play a Family Feud style answer board or a Jeopardy style category board.</p><footer><span class="tag">Play now</span><span>Open ↗</span></footer></button></div>${section('Matching games')}<div class="challenge-grid">${state.games.map(item=>challengeCard(item,true)).join('')}</div><p class="footnote">These exercises teach Orthodox positions and careful reasoning; a score is a study aid, not a measure of faith.</p>`}
function miniScreen(){const item=state.challenges.find(entry=>entry.id===state.selected&&entry.micro);if(!item){nav('challenges');return}if(!state.mini||state.mini.id!==item.id)state.mini={id:item.id,index:0,answers:[],hearts:3,feedback:null,busy:false,done:false,result:null,saveError:null};const run=state.mini,question=item.questions[run.index];screen.innerHTML=`<div class="mini-shell"><button class="text-button back" data-nav="challenges">← All lessons</button><div class="mini-progress"><div class="mini-progress-line" role="progressbar" aria-valuemin="0" aria-valuemax="${item.questions.length}" aria-valuenow="${run.done?item.questions.length:run.index}"><i style="width:${Math.round((run.done?item.questions.length:run.index)/item.questions.length*100)}%"></i></div><span aria-label="${run.hearts} hearts remaining">${'♥'.repeat(run.hearts)}${'♡'.repeat(3-run.hearts)}</span></div>${run.done?`<div class="card mini-finish"><span class="eyebrow">LESSON COMPLETE</span><h1>${esc(item.title)}</h1><div class="stat-number">${run.answers.filter((answer,index)=>answer===run.correctAnswers[index]).length}/${item.questions.length}</div><p>${run.result?`Saved to your profile · Best ${run.result.best_score}/${item.questions.length} · ${run.result.attempts} attempts`:state.user?.registered?run.saveError?`Could not save: ${esc(run.saveError)}`:'Saving your result…':'Sign in to save your progress across devices.'}</p><button class="primary" data-activity="${esc(item.id)}">Practice again</button> <button class="secondary" data-nav="challenges">All lessons</button>${!state.user?.registered?'<button class="secondary" data-action="signup">Create an account</button>':run.saveError?'<button class="secondary" data-mini-save>Retry saving</button>':''}</div>`:`<span class="eyebrow">${esc(item.track||'APOLOGETICS')} · STEP ${run.index+1} OF ${item.questions.length}</span><h1>${esc(item.title)}</h1><p class="lead">${esc(item.summary)}</p>${item.lessons?.[run.index]?`<section class="card mini-teaching"><span class="eyebrow">READ FIRST</span><h2>${esc(item.lessons[run.index].heading)}</h2><p>${esc(item.lessons[run.index].body)}</p></section>`:''}<section class="card mini-question"><span class="tag">${esc(item.level)}</span><h2>${esc(question.prompt)}</h2><div class="mini-choices">${question.choices.map((choice,index)=>`<button type="button" class="mini-choice ${run.feedback?(index===run.feedback.correct_choice?'correct':index===run.answers[run.index]?'incorrect':''):''}" data-mini-choice="${index}" ${run.feedback||run.busy?'disabled':''}>${esc(choice)}</button>`).join('')}</div>${run.feedback?`<div class="mini-feedback ${run.feedback.correct?'correct':'incorrect'}" role="status"><strong>${run.feedback.correct?'✓ That’s right':'↻ Learn this one'}</strong><p>${esc(run.feedback.explanation)}</p><button class="primary" data-mini-next>${run.index+1===item.questions.length?'Finish lesson':'Continue →'}</button></div>`:''}</section><p class="small">Based on <a href="${esc(item.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(item.source)} ↗</a></p>`}</div>`}
async function checkMiniChoice(event){const button=event.target.closest('[data-mini-choice]');if(!button||state.screen!=='mini'||!state.mini||state.mini.feedback||state.mini.busy)return;const run=state.mini,index=run.index,answer=Number(button.dataset.miniChoice);run.busy=true;button.disabled=true;try{const result=await api('/study/challenges/check','POST',{activity_id:run.id,question_index:index,answer});if(state.screen!=='mini'||state.mini!==run||run.index!==index)return;run.answers[index]=answer;run.correctAnswers??=[];run.correctAnswers[index]=result.correct_choice;run.feedback=result;if(!result.correct)run.hearts=Math.max(0,run.hearts-1);miniScreen()}catch(error){toast(error.message);button.disabled=false}finally{run.busy=false}}
async function saveMini(run){if(!state.user?.registered)return;run.saveError=null;try{const result=await api('/study/challenges/submit','POST',{activity_id:run.id,answers:run.answers});if(state.screen!=='mini'||state.mini!==run)return;run.result=result;state.challengeProgress=state.challengeProgress.filter(entry=>entry.activity_id!==run.id).concat({activity_id:run.id,best_score:result.best_score,attempts:result.attempts});miniScreen()}catch(error){if(state.screen==='mini'&&state.mini===run){run.saveError=error.message;miniScreen()}}}
async function nextMini(event){if(event.target.closest('[data-mini-save]')&&state.screen==='mini'&&state.mini?.done){const button=event.target.closest('[data-mini-save]');button.disabled=true;await saveMini(state.mini);return}if(!event.target.closest('[data-mini-next]')||state.screen!=='mini'||!state.mini?.feedback)return;const run=state.mini,lesson=state.challenges.find(item=>item.id===run.id);run.feedback=null;if(run.index+1<lesson.questions.length){run.index++;miniScreen();return}run.done=true;miniScreen();await saveMini(run)}
function activityScreen(){const item=state.challenges.find(entry=>entry.id===state.selected)||state.games.find(entry=>entry.id===state.selected);if(!item){nav('challenges');return}const game=!!item.prompts,saved=challengeScore(item.id);screen.innerHTML=`<div class="lesson-top"><button class="text-button back" data-nav="challenges">← Quizzes & games</button><span class="eyebrow">${esc(item.category.toUpperCase())} · ${game?'MATCHING GAME':esc(item.level.toUpperCase())}</span><h1>${esc(item.title)}</h1><p class="lead">${esc(item.summary)}</p>${saved?`<span class="tag">Personal best ${saved.best_score}/${game?item.prompts.length:item.questions.length} · ${saved.attempts} attempts</span>`:''}</div>${item.lessons?.length?`<div class="deep-lessons">${item.lessons.map((lesson,index)=>`<section class="card deep-lesson"><span class="eyebrow">STUDY NOTE ${String(index+1).padStart(2,'0')}</span><h2>${esc(lesson.heading)}</h2><p>${esc(lesson.body)}</p></section>`).join('')}</div>`:''}<div class="activity-layout"><section class="card"><span class="eyebrow">CHECK YOUR REASONING</span><h2>${game?'Match the ideas':'The challenge'}</h2><form id="challenge-form">${game?item.prompts.map((prompt,index)=>`<fieldset class="challenge-question"><legend><span class="question-number">${String(index+1).padStart(2,'0')}</span> ${esc(prompt)}</legend><label class="match-label">Match the answer<select name="answer-${index}" required><option value="">Choose an answer</option>${item.options.map((option,n)=>`<option value="${n}">${esc(option)}</option>`).join('')}</select></label></fieldset>`).join(''):item.questions.map((question,index)=>`<fieldset class="challenge-question"><legend><span class="question-number">${String(index+1).padStart(2,'0')}</span> ${esc(question.prompt)}</legend>${question.choices.map((choice,n)=>`<label class="challenge-choice"><input type="radio" name="answer-${index}" value="${n}" required><span>${esc(choice)}</span></label>`).join('')}</fieldset>`).join('')}<button class="primary" type="submit">Check my answers</button></form><div id="challenge-result" role="status" aria-live="polite"></div></section><aside class="card activity-aside"><span class="eyebrow">GO DEEPER</span><h2>Study the source</h2><p class="study-copy">Read the background after you answer. The explanations show why a choice works and why a shortcut may miss the point.</p><a class="secondary source-link" target="_blank" rel="noopener noreferrer" href="${esc(item.sourceUrl)}">${esc(item.source)} ↗</a>${item.furtherReading?.length?`<div class="further-reading"><strong>Compare the sources</strong>${item.furtherReading.map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.label)} ↗</a>`).join('')}</div>`:''}<p class="small">Your answers are checked by the app. Only your best score and number of attempts are saved to your profile.</p></aside></div>`}
async function submitChallenge(event){if(event.target.id!=='challenge-form')return;event.preventDefault();if(!state.user?.registered){showDialog('signup');return}const item=state.challenges.find(entry=>entry.id===state.selected)||state.games.find(entry=>entry.id===state.selected),game=!!item.prompts,form=new FormData(event.target),length=game?item.prompts.length:item.questions.length,raw=Array.from({length},(_,i)=>form.get(`answer-${i}`));if(raw.some(value=>value===null||value==='')){toast('Answer every question first.');return}const button=event.target.querySelector('[type=submit]');button.disabled=true;try{const result=await api('/study/challenges/submit','POST',{activity_id:item.id,answers:raw.map(Number)});const saved=challengeScore(item.id);state.challengeProgress=state.challengeProgress.filter(entry=>entry.activity_id!==item.id).concat({activity_id:item.id,best_score:Math.max(saved?.best_score||0,result.score),attempts:result.attempts});$('#challenge-result').innerHTML=`<div class="challenge-results"><span class="eyebrow">YOUR RESULT</span><h2>${result.score} / ${result.total}</h2><p class="muted">Best ${result.best_score}/${result.total} · Attempt ${result.attempts}</p>${result.explanations.map((explanation,index)=>`<div class="answer-review ${result.correct[index]?'correct':'incorrect'}"><strong>${result.correct[index]?'✓ Correct':'✗ Review'} · ${index+1}</strong><p>${esc(explanation)}</p></div>`).join('')}<button class="secondary" data-activity="${esc(item.id)}">Try again</button></div>`;$('#challenge-result').scrollIntoView({behavior:'smooth',block:'start'})}catch(error){toast(error.message)}finally{button.disabled=false}}
function render(){if(state.screen==='trivia')TriviaGame.show(screen,{api,user:()=>state.user,promptSignup:()=>showDialog('signup'),toast,back:()=>nav('challenges')});else if(state.screen==='bible')BibleReader.show(screen,{api,userId:()=>state.user?.id||null,isRegistered:()=>!!state.user?.registered,promptSignup:()=>showDialog('signup'),toast});else if(state.screen==='today')today();else if(state.screen==='library')library();else if(state.screen==='study')reader();else if(state.screen==='practice')practice();else if(state.screen==='notes')notes();else if(state.screen==='challenges')challengesScreen();else if(state.screen==='activity')activityScreen();else if(state.screen==='mini')miniScreen();else profile()}
function field(label,name,type='text',value='',attrs=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function dialog(title,description,fields,submit,extra=''){overlay.hidden=false;$('#dialog-content').innerHTML=`<span class="eyebrow">MIND SOUL AND BODY · YOUR PROFILE</span><h2 id="dialog-title">${esc(title)}</h2><p>${esc(description)}</p><form id="dialog-form" novalidate><p class="form-error" role="alert" hidden></p>${fields}<button class="primary" type="submit">${esc(submit)}</button></form><div class="dialog-links">${extra}</div>`;$('#dialog-form').onsubmit=handleDialog}
function closeDialog(){overlay.hidden=true;$('#dialog-content').innerHTML=''}
function showRecovery(code){state.dialog='recovery-display';overlay.hidden=false;$('#dialog-content').innerHTML=`<span class="eyebrow">SAVE THIS ONCE</span><h2 id="dialog-title">Your recovery code</h2><p>Keep this somewhere private. If you forget your password, this code can reset it once. It will not appear here again.</p><p class="recovery-code">${esc(code)}</p><button class="primary" data-close>I've saved my code</button>`}
function showDialog(kind){state.dialog=kind;const p=state.profile||{};if(kind==='signup')return dialog('Create your study profile','Save notes and progress across devices.',field('Name','name','text',p.registered?'':p.name||'','required minlength="2" maxlength="60" autocomplete="name"')+field('Username','handle','text',p.registered?'':p.handle?.startsWith('guest_')?'':p.handle||'','required pattern="[a-zA-Z0-9_]{3,24}" autocomplete="username"')+field('City (optional)','city','text',p.city||'','maxlength="80"')+field('Email','email','email','','required autocomplete="email"')+field('Password','password','password','','required minlength="10" autocomplete="new-password"'),'Create account','<button data-action="signin">Already have an account? Sign in</button>');
if(kind==='signin')return dialog('Welcome back','Sign in to open your study journal.',field('Email or username','identifier','text','','required autocomplete="username"')+field('Password','password','password','','required autocomplete="current-password"'),'Sign in','<button data-action="signup">Create account</button><button data-action="forgot">Forgot password?</button>');
if(kind==='forgot'){if(!state.emailResetReady)return showDialog('recovery-reset');return dialog('Reset your password','Enter the email on your account. If it exists, we will send a code.',field('Account email','email','email',state.resetEmail,'required autocomplete="email"'),'Email a reset code','<button data-action="recovery-reset">Use a saved recovery code</button><button data-action="email-code">Already have an email code?</button>')}
if(kind==='email-code')return dialog('Enter your email code','The eight-digit code expires after 15 minutes.',field('Account email','email','email',state.resetEmail,'required autocomplete="email"')+field('Email code','code','text','','required inputmode="numeric" pattern="[0-9]{8}" maxlength="8" autocomplete="one-time-code"')+field('New password','new_password','password','','required minlength="10" autocomplete="new-password"'),'Set new password','<button data-action="forgot">Request another code</button>');
if(kind==='recovery-reset')return dialog('Use your recovery code','Use the one-use code shown when you created your account.',field('Account email','email','email','','required autocomplete="email"')+field('Recovery code','code','text','','required autocomplete="off"')+field('New password','new_password','password','','required minlength="10" autocomplete="new-password"'),'Reset password',state.emailResetReady?'<button data-action="forgot">Email a code instead</button>':'');
if(kind==='change-password')return dialog('Change password','Your other devices will be signed out.',field('Current password','current_password','password','','required autocomplete="current-password"')+field('New password','new_password','password','','required minlength="10" autocomplete="new-password"'),'Save password');
if(kind==='recovery-code')return dialog('New recovery code','Your previous code will stop working.',field('Current password','current_password','password','','required autocomplete="current-password"'),'Generate code');
if(kind==='edit-profile')return dialog('Edit your profile','Keep your study profile personal.',field('Name','name','text',p.name,'required minlength="2" maxlength="60"')+field('Username','handle','text',p.handle,'required pattern="[a-zA-Z0-9_]{3,24}"')+field('City','city','text',p.city||'','maxlength="80"')+`<label>Bio<textarea name="bio" maxlength="160">${esc(p.bio||'')}</textarea></label>`+(p.registered?field('Email','email','email',p.email,'required')+field('Current password (only if changing email)','current_password','password','','autocomplete="current-password"'):'')+'<label>Portrait · JPG, PNG or WebP, up to 5 MB<input type="file" name="avatar" accept="image/jpeg,image/png,image/webp"></label><label>Cover photo · up to 5 MB<input type="file" name="cover" accept="image/jpeg,image/png,image/webp"></label>','Save profile')}
function showFormError(form,message){let el=form.querySelector('.form-error');if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');form.prepend(el)}el.hidden=false;el.textContent=message;el.scrollIntoView({block:'nearest'})}
async function handleDialog(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]'),invalid=[...form.elements].find(el=>el instanceof HTMLInputElement||el instanceof HTMLTextAreaElement? !el.checkValidity():false);if(invalid){showFormError(form,`${invalid.closest('label')?.childNodes[0]?.textContent?.trim()||'This field'}: ${invalid.validationMessage}`);invalid.focus();return}const data=new FormData(form),kind=state.dialog;button.disabled=true;const label=button.textContent;button.textContent='Working…';try{if(kind==='signup'){const result=await api('/auth/register','POST',{name:data.get('name'),handle:data.get('handle'),city:data.get('city'),email:data.get('email'),password:data.get('password')});if(!result.token||!result.user||!result.recovery_code)throw Error('Account creation did not finish. Try signing in before creating another account.');state.token=result.token;localStorage.setItem('aura_token',result.token);localStorage.removeItem('ic_token');state.user=result.user;showRecovery(result.recovery_code);try{await loadAccount();nav('today')}catch{toast('Account created. Save your recovery code, then reload to open your profile.')}return}
if(kind==='signin'){const result=await api('/auth/login','POST',{identifier:data.get('identifier'),password:data.get('password')});state.token=result.token;localStorage.setItem('aura_token',result.token);localStorage.removeItem('ic_token');state.user=result.user;await loadAccount();closeDialog();nav('today');toast('Welcome back.');return}
if(kind==='forgot'){state.resetEmail=String(data.get('email')||'').trim();await api('/auth/email-reset-request','POST',{email:state.resetEmail});showDialog('email-code');toast('If the account exists, a code is on its way.');return}
if(kind==='email-code'||kind==='recovery-reset'){await api(kind==='email-code'?'/auth/email-reset':'/auth/reset','POST',{email:data.get('email'),code:data.get('code'),new_password:data.get('new_password')});state.token='';state.user=null;state.profile=null;localStorage.removeItem('aura_token');localStorage.removeItem('ic_token');showDialog('signin');toast('Password reset. Sign in with your new password.');return}
if(kind==='change-password'){await api('/auth/password','POST',{current_password:data.get('current_password'),new_password:data.get('new_password')});closeDialog();toast('Password updated.');return}
if(kind==='recovery-code'){const result=await api('/auth/recovery-code','POST',{current_password:data.get('current_password')});showRecovery(result.recovery_code);return}
if(kind==='edit-profile'){for(const key of ['avatar','cover']){const file=data.get(key);if(file instanceof File&&file.size>5000000)throw Error('Choose photos under 5 MB.')}await api('/profile','POST',{name:data.get('name'),handle:data.get('handle'),city:data.get('city'),bio:data.get('bio'),...(state.profile.registered?{email:data.get('email'),current_password:data.get('current_password')}:{})});for(const key of ['avatar','cover']){const file=data.get(key);if(file instanceof File&&file.size){const upload=new FormData();upload.set('file',file);await api(key==='avatar'?'/profile/avatar':'/profile/cover','POST',upload)}}await loadAccount();closeDialog();nav('profile');toast('Profile saved.');return}}
catch(error){showFormError(form,error?.message||'Something went wrong. Please try again.');button.disabled=false;button.textContent=label}}
async function action(event){const themeButton=event.target.closest('[data-theme-choice]');if(themeButton){applyTheme(themeButton.dataset.themeChoice);profile();return}const button=event.target.closest('[data-action],[data-nav],[data-lesson],[data-filter],[data-activity],[data-bible-open],[data-daily-read],[data-close]');if(!button)return;if(button.hasAttribute('data-close')){closeDialog();return}if(button.hasAttribute('data-daily-read')){const ref=dailyCard();BibleReader.open(ref.book,ref.chapter);nav('bible');return}if(button.dataset.nav){nav(button.dataset.nav);return}if(button.dataset.lesson){nav('study',button.dataset.lesson);return}if(button.dataset.bibleOpen){const refs={word:[43,1],beatitudes:[40,5],mercy:[42,15],faith:[59,2],resurrection:[46,15],renewal:[19,51]};const ref=refs[button.dataset.bibleOpen];if(ref){BibleReader.open(...ref);nav('bible')}return}if(button.dataset.activity){const activity=state.challenges.find(item=>item.id===button.dataset.activity);nav(activity?.micro?'mini':'activity',button.dataset.activity);return}if(button.dataset.filter){state.filter=button.dataset.filter;library();return}const kind=button.dataset.action;if(['signup','signin','forgot','email-code','recovery-reset','edit-profile','change-password','recovery-code'].includes(kind)){showDialog(kind);return}if(kind==='logout'){try{await api('/auth/logout','POST',{});state.token='';state.user=null;state.profile=null;applyTheme('teal',false);state.notes=[];state.progress=[];state.challengeProgress=[];BibleReader.resetAccount();localStorage.removeItem('aura_token');localStorage.removeItem('ic_token');closeDialog();nav('today');toast('Signed out.')}catch(error){toast(error.message)}return}if(kind==='save-note'){if(!state.user?.registered){showDialog('signup');return}button.disabled=true;try{const body=$('#study-note').value;const result=await api('/study/notes','POST',{study_id:state.selected,body});state.notes=state.notes.filter(item=>item.study_id!==state.selected);if(result.body)state.notes.push({study_id:state.selected,body:result.body,updated_at:result.updated_at});$('#note-status').textContent='Saved to your profile';toast('Note saved.')}catch(error){toast(error.message)}finally{button.disabled=false}return}if(kind==='toggle-complete'){if(!state.user?.registered){showDialog('signup');return}button.disabled=true;try{const previous=progress(state.selected),done=!!previous?.completed_at,result=await api('/study/complete','POST',{study_id:state.selected,complete:!done});state.progress=state.progress.filter(item=>item.study_id!==state.selected);state.progress.push({...previous,study_id:state.selected,completed_at:result.completed_at,quiz_score:previous?.quiz_score??null});reader();toast(done?'Marked unfinished.':'Study completed.')}catch(error){toast(error.message);button.disabled=false}}}
async function submitQuiz(event){if(event.target.id!=='quiz-form')return;event.preventDefault();if(!state.user?.registered){showDialog('signup');return}const item=study(state.selected),form=new FormData(event.target),answers=item.quiz.map((_,index)=>Number(form.get(`question-${index}`)));if(item.quiz.some((_,index)=>form.get(`question-${index}`)===null)){toast('Answer both questions first.');return}const button=event.target.querySelector('[type=submit]');button.disabled=true;try{const result=await api('/study/quiz','POST',{study_id:item.id,answers});state.progress=state.progress.filter(row=>row.study_id!==item.id).concat({...progress(item.id),study_id:item.id,quiz_score:result.score});$('#quiz-result').innerHTML=`<div class="quiz-result"><strong>${result.score} of ${result.total} correct</strong>${result.explanations.map((explanation,index)=>`<p>${result.correct[index]?'✓':'✗'} ${esc(explanation)}</p>`).join('')}</div>`;toast('Your result was saved.')}catch(error){toast(error.message)}finally{button.disabled=false}}
document.addEventListener('click',action);screen.addEventListener('click',event=>TriviaGame.click(event));screen.addEventListener('click',checkMiniChoice);screen.addEventListener('click',nextMini);screen.addEventListener('submit',submitQuiz);screen.addEventListener('submit',submitChallenge);screen.addEventListener('input',event=>{if(event.target.id==='study-note')$('#note-status').textContent='Unsaved changes'});overlay.addEventListener('click',event=>{if(event.target===overlay)closeDialog()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!overlay.hidden)closeDialog()});
async function boot(){try{const [library,config,session,challengeLibrary]=await Promise.all([api('/study/library'),api('/auth/reset-config'),api('/auth/session'),api('/study/challenges')]);state.studies=library.studies||[];state.challenges=challengeLibrary.challenges||[];state.games=challengeLibrary.games||[];state.emailResetReady=!!config.enabled;state.user=session.user;if(state.user)await loadAccount();render()}catch(error){screen.innerHTML=`<div class="empty error">${esc(error.message)} <button class="secondary" onclick="location.reload()">Try again</button></div>`}}
let MSB_LOCAL=false;
boot();

/* ---- Standalone mode (static hosting, e.g. GitHub Pages): no /api backend. ----
   api() above is kept as the remote client (renamed apiRemote). The first time the
   remote layer reports the backend is not on this origin (404/501 or unreachable),
   the session switches to the local implementations below: bundled study content
   from data/*.json, one local owner profile, and user data in localStorage. (MSB_LOCAL is declared just above boot() so boot's first call can read it.) */
const MSB_STORE_KEY='msb_local_v1';
function msbStore(){try{const raw=localStorage.getItem(MSB_STORE_KEY);if(raw)return JSON.parse(raw)}catch{}const fresh={profile:{id:'local',name:'Angel',handle:'angel',city:'',bio:'',email:'',registered:true,avatar_key:null,cover_key:null,avatar_data:null,cover_data:null},password:null,recovery_code:null,email_code:null,signedOut:false,progress:[],notes:[],challenges:[],highlights:[],place:null};msbSave(fresh);return fresh}
function msbSave(store){try{localStorage.setItem(MSB_STORE_KEY,JSON.stringify(store))}catch{}}
let msbLibraryCache=null,msbChallengesCache=null,msbTriviaCache=null;
async function msbBundled(url){const res=await fetch(url,{cache:'no-store'});if(!res.ok)throw Error(`Bundled content is missing (${res.status}).`);return res.json()}
function msbCode(length){const chars='ABCDEFGHJKMNPQRSTUVWXYZ23456789';let out='';for(let i=0;i<length;i++)out+=chars[Math.floor(Math.random()*chars.length)];return out}
function msbImageData(file,max){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{const scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',0.85))}catch(error){reject(error)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('That photo could not be read.'))};img.src=url})}
const MSB_UNSCORED='Answer keys were kept on the old server, so answers cannot be scored in this offline copy. The readings and lessons still work, and your notes, highlights, and completion save on this device.';
async function localApi(path,method='GET',body){
  const clean=path.split('?')[0],store=msbStore(),p=store.profile;
  if(clean==='/study/library'){if(!msbLibraryCache)msbLibraryCache=await msbBundled('data/study-library.json');return msbLibraryCache}
  if(clean==='/study/challenges'){if(!msbChallengesCache){const res=await fetch('data/study-challenges.json',{cache:'force-cache'});if(!res.ok)throw Error(`Bundled content is missing (${res.status}).`);msbChallengesCache=await res.json()}return msbChallengesCache}
  if(clean==='/study/trivia'){if(!msbTriviaCache)msbTriviaCache=await msbBundled('data/trivia.json');return msbTriviaCache}
  if(clean==='/auth/reset-config')return{enabled:false};
  if(clean==='/auth/session')return{user:store.signedOut?null:{id:p.id,registered:true}};
  if(clean==='/auth/register'){Object.assign(p,{name:body?.name||p.name,handle:body?.handle||p.handle,city:body?.city||'',email:body?.email||p.email,registered:true});if(body?.password)store.password=body.password;store.recovery_code=msbCode(12);store.signedOut=false;msbSave(store);return{token:'local',user:{id:p.id,registered:true},recovery_code:store.recovery_code}}
  if(clean==='/auth/login'){if(store.password&&body?.password!==store.password)throw Error('That password does not match this device profile.');store.signedOut=false;msbSave(store);return{token:'local',user:{id:p.id,registered:true}}}
  if(clean==='/auth/logout'){store.signedOut=true;msbSave(store);return{}}
  if(clean==='/auth/password'){if(store.password&&body?.current_password!==store.password)throw Error('Current password is not correct.');if(body?.new_password)store.password=body.new_password;msbSave(store);return{}}
  if(clean==='/auth/recovery-code'){if(store.password&&body?.current_password!==store.password)throw Error('Current password is not correct.');store.recovery_code=msbCode(12);msbSave(store);return{recovery_code:store.recovery_code}}
  if(clean==='/auth/email-reset-request'){store.email_code=String(Math.floor(10000000+Math.random()*90000000));msbSave(store);return{}}
  if(clean==='/auth/email-reset'||clean==='/auth/reset'){const expected=clean==='/auth/reset'?store.recovery_code:store.email_code;if(!expected||body?.code!==expected)throw Error('That code is not correct.');if(body?.new_password)store.password=body.new_password;store.email_code=null;msbSave(store);return{}}
  if(clean==='/me')return p;
  if(clean==='/profile'&&method==='POST'){Object.assign(p,{name:body?.name||p.name,handle:body?.handle||p.handle,city:body?.city||'',bio:body?.bio||''});if(body?.email)p.email=body.email;msbSave(store);return p}
  if(clean==='/profile/avatar'||clean==='/profile/cover'){const file=body&&typeof body.get==='function'?body.get('file'):null;if(file){const url=await msbImageData(file,clean.endsWith('cover')?1024:256);if(clean.endsWith('avatar')){p.avatar_data=url;p.avatar_key='local'}else{p.cover_data=url;p.cover_key='local'}msbSave(store)}return{}}
  if(clean==='/study/dashboard')return{progress:store.progress,notes:store.notes,challenges:store.challenges};
  if(clean==='/study/notes'){const text=String(body?.body||''),entry={study_id:body?.study_id,body:text,updated_at:Math.floor(Date.now()/1000)};store.notes=store.notes.filter(entry2=>entry2.study_id!==entry.study_id);if(text.trim())store.notes.push(entry);msbSave(store);return text.trim()?entry:{body:'',updated_at:entry.updated_at}}
  if(clean==='/study/complete'){const previous=store.progress.find(row=>row.study_id===body?.study_id),row={study_id:body?.study_id,completed_at:body?.complete?Math.floor(Date.now()/1000):null,quiz_score:previous?.quiz_score??null};store.progress=store.progress.filter(entry=>entry.study_id!==row.study_id);store.progress.push(row);msbSave(store);return{completed_at:row.completed_at}}
  if(clean==='/study/challenges/check')return{correct:false,correct_choice:-1,explanation:'This offline copy has no answer key (the keys were kept on the old server), so your answer cannot be checked here. Compare it with the reading, then continue — nothing is scored or saved for this step.'};
  if(clean==='/study/quiz'||clean==='/study/challenges/submit')throw Error(MSB_UNSCORED);
  if(clean==='/bible/state')return{highlights:store.highlights,place:store.place};
  if(clean==='/bible/highlight'){const book_id=body?.book_id,chapter=body?.chapter,verse=body?.verse,color=body?.color;store.highlights=store.highlights.filter(item=>!(item.book_id===book_id&&item.chapter===chapter&&item.verse===verse));if(!color){msbSave(store);return{}}const entry={book_id,chapter,verse,color};store.highlights.unshift(entry);msbSave(store);return entry}
  if(clean==='/bible/place'){store.place={book_id:body?.book_id,chapter:body?.chapter};msbSave(store);return{}}
  if(clean.startsWith('/study/trivia/'))throw Error('Trivia answer-checking and friend rooms were run by the old server, so they are unavailable in this offline copy. The boards and questions still open for practice.');
  throw Error('That part of the app needed the old server and is not available in this offline copy.');
}
async function api(path,method='GET',body){if(MSB_LOCAL)return localApi(path,method,body);try{return await apiRemote(path,method,body)}catch(error){if(error?.status===404||error?.status===501||error?.offline){MSB_LOCAL=true;return localApi(path,method,body)}throw error}}
